```js
function resumenDelDia(ventas, minimo) {
  const validas = ventas.filter((v) => v >= minimo);
  if (validas.length === 0) {
    return [0, 0, 0, 0];
  }
  const total = validas.reduce((acc, v) => acc + v, 0);
  const mayor = validas.reduce((acc, v) => (v > acc ? v : acc), validas[0]);
  return [validas.length, total, total / validas.length, mayor];
}
```

