function nombreLimpio(texto) {
  return texto
    .trim()
    .split(" ")
    .filter((p) => p !== "")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(" ");
}

function sumarDias(iso, n) {
  const d = new Date(iso);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString();
}

function textoCita(nombre, iso) {
  const d = new Date(iso);
  const dos = (n) => String(n).padStart(2, "0");
  const limpio = nombre
    .trim()
    .split(" ")
    .filter((p) => p !== "")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(" ");
  const fecha = dos(d.getUTCDate()) + "/" + dos(d.getUTCMonth() + 1) + "/" + d.getUTCFullYear();
  const hora = dos(d.getUTCHours()) + ":" + dos(d.getUTCMinutes());
  return "Hola " + limpio + ": tu cita es el " + fecha + " a las " + hora + " (UTC)";
}

